# Surah Al-A'raf (chapter 7) — part 17: ayat 165-174 (IDs 1119-1128)
SURAH = 7

ENTRIES = {
1119: (
"پس — جب — انہوں نے — اس — نصیحت کو بھول گئے — جو انہیں دی گئی تھی — ہم نے — ان لوگوں کو — جو برائی سے روکتے تھے — بچایا — اور — ظلم کرنے والوں کو — ان کے — فاسق ہونے کی وجہ سے — سخت عذاب میں پکڑ لیا",
"""۱۔ برائی سے روکنے والے — محفوظ؛ ظالموں — ہلاک۔
۲۔ ’’فَلَمَّا نَسُوا مَا ذُكِّرُوا بِهِ أَنجَيْنَا الَّذِينَ يَنْهَوْنَ عَنِ السُّوءِ وَأَخَذْنَا الَّذِينَ ظَلَمُوا بِعَذَابٍ بَئِيسٍ بِمَا كَانُوا يَفْسُقُونَ‘‘ — پس — جب — انہوں نے — اس — نصیحت کو بھول گئے — جو انہیں دی گئی تھی — ہم نے — ان لوگوں کو — جو برائی سے روکتے تھے — بچایا — اور — ظلم کرنے والوں کو — ان کے — فاسق ہونے کی وجہ سے — سخت عذاب میں پکڑ لیا — یعنی نصیحت کو فراموش کرنے والے — ہلاک ہو گئے؛ برائی سے روکنے والے — بچ گئے۔
۳۔ عملی سبق: برائی سے روکنا — نجات کا ذریعہ ہے۔"""
),
1120: (
"پس — جب — انہوں نے — اس — سے — حد سے تجاوز کیا — جس سے انہیں منع کیا گیا تھا — ہم نے انہیں کہا — ذلیل بندر — بن جاؤ",
"""۱۔ بنی اسرائیل — حد پار کر کے — بندر بنا دیے گئے۔
۲۔ ’’فَلَمَّا عَتَوْا عَن مَّا نُهُوا عَنْهُ قُلْنَا لَهُمْ كُونُوا قِرَدَۃً خَاسِئِينَ‘‘ — پس — جب — انہوں نے — اس — سے — حد سے تجاوز کیا — جس سے انہیں منع کیا گیا تھا — ہم نے انہیں کہا — ذلیل بندر — بن جاؤ — یعنی اللہ — نافرمانی کی سزا میں انہیں — بندر — بنا دیا۔
۳۔ عملی سبق: اللہ کی حدود سے تجاوز — تباہی اور ذلت کا سبب ہے۔"""
),
1121: (
"اور — جب — تمہارے رب نے — اعلان کیا — کہ — وہ — ان پر — قیامت تک — ایسے — لوگ بھیجے گا — جو — انہیں — برا عذاب دیں — بے شک — تمہارا رب — جلدی سزا دینے والا ہے — اور — بے شک — وہ — بخشنے والا مہربان ہے",
"""۱۔ بنی اسرائیل پر — قیامت تک — تسلط۔
۲۔ ’’وَإِذْ تَأَذَّنَ رَبُّكَ لَيَبْعَثَنَّ عَلَيْهِمْ إِلَىٰ يَوْمِ الْقِيَامَۃِ مَن يَسُومُهُمْ سُوءَ الْعَذَابِ إِنَّ رَبَّكَ لَسَرِيعُ الْعِقَابِ وَإِنَّهُ لَغَفُورٌ رَّحِيمٌ‘‘ — اور — جب — تمہارے رب نے — اعلان کیا — کہ — وہ — ان پر — قیامت تک — ایسے — لوگ بھیجے گا — جو — انہیں — برا عذاب دیں — بے شک — تمہارا رب — جلدی سزا دینے والا ہے — اور — بے شک — وہ — بخشنے والا مہربان ہے — یعنی بنی اسرائیل پر — قیامت تک — جو ظلم کرتے ہیں — وہ — خدا کی طرف سے سزا ہے۔
۳۔ عملی سبق: اللہ کی سزا — فوری اور قطعی ہے۔"""
),
1122: (
"اور ہم نے — انہیں — زمین میں — امتوں میں تقسیم کر دیا — ان — میں سے — کچھ نیک ہیں — اور — کچھ اس سے کم — اور — ہم — نے — انہیں آسودگی اور مصیبت — سے — آزمایا — شاید — وہ لوٹ آئیں",
"""۱۔ بنی اسرائیل — مختلف امتوں میں — بکھر گئے — اچھے اور برے — دونوں۔
۲۔ ’’وَقَطَّعْنَاهُمْ فِي الْأَرْضِ أُمَمًا مِّنْهُمُ الصَّالِحُونَ وَمِنْهُمْ دُونَ ذَٰلِكَ وَبَلَوْنَاهُم بِالْحَسَنَاتِ وَالسَّيِّئَاتِ لَعَلَّهُمْ يَرْجِعُونَ‘‘ — اور ہم نے — انہیں — زمین میں — امتوں میں تقسیم کر دیا — ان — میں سے — کچھ نیک ہیں — اور — کچھ اس سے کم — اور — ہم — نے — انہیں آسودگی اور مصیبت — سے — آزمایا — شاید — وہ لوٹ آئیں — یعنی بنی اسرائیل — مختلف طبقوں میں — بٹ گئے — اور — دونوں حالتوں سے — ان کا امتحان لیا گیا۔
۳۔ عملی سبق: آسودگی و مصیبت دونوں — آزمائش ہیں؛ ناشکری نہ کرو۔"""
),
1123: (
"پس — ان کے بعد — ایک جماعت — ان کا جانشین — بنی — جنہوں نے — کتاب — وراثت میں پائی — وہ — اس — دنیا کی — عارضی — متاع — لے لیتے ہیں — اور کہتے ہیں — عنقریب — ہمیں — بخش دیا جائے گا — اور — اگر — انہیں — اسی — جیسی — متاع ملے — وہ — اسے — بھی — لے لیں — کیا — ان — سے کتاب کا عہد نہیں لیا گیا — کہ وہ — اللہ پر — صرف حق — کہیں — اور وہ — اس کا — مطالعہ کر چکے تھے — اور — آخرت کا گھر — متقیوں کے لیے بہتر ہے — کیا — تم — نہیں سمجھتے",
"""۱۔ بعد کے لوگ — کتاب کی وارثت لے کر بھی — دنیا کے پیچھے۔
۲۔ ’’فَخَلَفَ مِن بَعْدِهِمْ خَلْفٌ وَرِثُوا الْكِتَابَ يَأْخُذُونَ عَرَضَ هَٰذَا الْأَدْنَىٰ وَيَقُولُونَ سَيُغْفَرُ لَنَا وَإِن يَأْتِهِمْ عَرَضٌ مِّثْلُهُ يَأْخُذُوهُ أَلَمْ يُؤْخَذْ عَلَيْهِم مِّيثَاقُ الْكِتَابِ أَن لَّا يَقُولُوا عَلَى اللَّهِ إِلَّا الْحَقَّ وَدَرَسُوا مَا فِيهِ وَالدَّارُ الْآخِرَۃُ خَيْرٌ لِّلَّذِينَ يَتَّقُونَ أَفَلَا تَعْقِلُونَ‘‘ — پس — ان کے بعد — ایک جماعت — ان کا جانشین — بنی — جنہوں نے — کتاب — وراثت میں پائی — وہ — اس — دنیا کی — عارضی — متاع — لے لیتے ہیں — اور کہتے ہیں — عنقریب — ہمیں — بخش دیا جائے گا — اور — اگر — انہیں — اسی — جیسی — متاع ملے — وہ — اسے — بھی — لے لیں — کیا — ان — سے کتاب کا عہد نہیں لیا گیا — کہ وہ — اللہ پر — صرف حق — کہیں — اور وہ — اس کا — مطالعہ کر چکے تھے — اور — آخرت کا گھر — متقیوں کے لیے بہتر ہے — کیا — تم — نہیں سمجھتے — یعنی بعد والے — کتاب پڑھ کر بھی دنیا کے پیچھے — جا رہے ہیں — حلال و حرام میں تفریق نہیں کرتے۔
۳۔ عملی سبق: علم کے باوجود — دھتکار — نہیں؛ اللہ کے حکم کو — عمل میں لاؤ۔"""
),
1124: (
"اور — جو لوگ — کتاب کو مضبوطی سے پکڑتے ہیں — اور نماز قائم کرتے ہیں — بے شک — ہم — نیک عمل کرنے والوں کا — اجر — ضائع نہیں کرتے",
"""۱۔ کتاب سے مضبوط تعلق — اور نماز — نجات۔
۲۔ ’’وَالَّذِينَ يُمَسِّكُونَ بِالْكِتَابِ وَأَقَامُوا الصَّلَاۃَ إِنَّا لَا نُضِيعُ أَجْرَ الْمُصْلِحِينَ‘‘ — اور — جو لوگ — کتاب کو مضبوطی سے پکڑتے ہیں — اور نماز قائم کرتے ہیں — بے شک — ہم — نیک عمل کرنے والوں کا — اجر — ضائع نہیں کرتے — یعنی کتاب کی پیروی اور نماز — سب سے بڑا نجات کا راستہ ہے۔
۳۔ عملی سبق: کتاب کی مضبوطی اور نماز کی لپٹ — لازم ہے۔"""
),
1125: (
"اور — جب — ہم — نے — پہاڑ — ان — کے اوپر — اٹھایا — گویا — وہ — ایک — چھتری — ہے — اور انہوں نے — وہ — نیچے آنے والا — سمجھا — لو — جو ہم نے تمہیں دیا — اسے مضبوطی سے پکڑو — اور — اس میں جو ہے — اسے یاد کرو — شاید — تم — تقویٰ اختیار کرو",
"""۱۔ کوہِ طور — بنی اسرائیل کے اوپر اٹھایا گیا — عہد یاد رکھنے کے لیے۔
۲۔ ’’وَإِذْ نَتَقْنَا الْجَبَلَ فَوْقَهُمْ كَأَنَّهُ ظُلَّۃٌ وَظَنُّوا أَنَّهُ وَاقِعٌ بِهِمْ خُذُوا مَا آتَيْنَاكُم بِقُوَّۃٍ وَاذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ‘‘ — اور — جب — ہم — نے — پہاڑ — ان — کے اوپر — اٹھایا — گویا — وہ — ایک — چھتری — ہے — اور انہوں نے — وہ — نیچے آنے والا — سمجھا — لو — جو ہم نے تمہیں دیا — اسے مضبوطی سے پکڑو — اور — اس میں جو ہے — اسے یاد کرو — شاید — تم — تقویٰ اختیار کرو — یعنی بنی اسرائیل پر — پہاڑ اٹھا کر — انہیں — اللہ کے حکم کی یاد دہانی کرائی گئی۔
۳۔ عملی سبق: اللہ کے احکام — مضبوطی اور یادداشت کے ساتھ اپناؤ۔"""
),
1126: (
"اور — یاد کرو — جب — تمہارے رب نے — آدم کی اولاد کی پیٹھوں سے — ان کی — نسل — نکالی — اور — انہیں — خود اپنے اوپر گواہ بنایا — کیا — میں تمہارا رب نہیں ہوں — انہوں نے کہا — ہاں — ہم گواہ ہیں — یہ — اس لیے کہ — قیامت کے دن — تم — یہ — نہ کہو — ہم — اس — سے غافل تھے",
"""۱۔ ذرّیوں سے — اللہ کا عہد — الست بربکم۔
۲۔ ’’وَإِذْ أَخَذَ رَبُّكَ مِن بَنِي آدَمَ مِن ظُهُورِهِمْ ذُرِّيَّتَهُمْ وَأَشْهَدَهُمْ عَلَىٰ أَنفُسِهِمْ أَلَسْتُ بِرَبِّكُمْ قَالُوا بَلَىٰ شَهِدْنَا أَن تَقُولُوا يَوْمُ الْقِيَامَۃِ إِنَّا كُنَّا عَنْ هَٰذَا غَافِلِينَ‘‘ — اور — یاد کرو — جب — تمہارے رب نے — آدم کی اولاد کی پیٹھوں سے — ان کی — نسل — نکالی — اور — انہیں — خود اپنے اوپر گواہ بنایا — کیا — میں تمہارا رب نہیں ہوں — انہوں نے کہا — ہاں — ہم گواہ ہیں — یہ — اس لیے کہ — قیامت کے دن — تم — یہ — نہ کہو — ہم — اس — سے غافل تھے — یعنی اللہ — انسانوں سے — ان کی پیدائش سے پہلے — رب ہونے کا عہد لیتا ہے۔
۳۔ عملی سبق: اللہ کا رب ہونا — انسان کی فطرت میں — درج ہے۔"""
),
1127: (
"یا — یہ — نہ کہو — ہمارے باپ دادا نے — پہلے — شرک کیا تھا — اور — ہم — ان کے بعد — نسل تھے — پس — کیا — تو — ہمیں — ان باطل لوگوں کے کیے — پر — ہلاک کرے گا",
"""۱۔ باپ دادا کی گمراہی — عذاب کا عذر نہیں۔
۲۔ ’’أَوْ تَقُولُوا إِنَّمَا أَشْرَكَ آبَاؤُنَا مِن قَبْلُ وَكُنَّا ذُرِّيَّۃً مِّن بَعْدِهِمْ أَفَتُهْلِكُنَا بِمَا فَعَلَ الْمُبْطِلُونَ‘‘ — یا — یہ — نہ کہو — ہمارے باپ دادا نے — پہلے — شرک کیا تھا — اور — ہم — ان کے بعد — نسل تھے — پس — کیا — تو — ہمیں — ان باطل لوگوں کے کیے — پر — ہلاک کرے گا — یعنی اپنے باپ دادا کی گمراہی کی وجہ — شرک کرنا — قابلِ عذر نہیں۔
۳۔ عملی سبق: باپ دادا کی تقلید — حق سے نہیں؛ ایمان خود اپناؤ۔"""
),
1128: (
"اور — اسی طرح — ہم — آیات کو تفصیل سے — بیان کر رہے ہیں — اور شاید — وہ — لوٹ آئیں",
"""۱۔ آیات — لوٹنے والوں کے لیے۔
۲۔ ’’وَكَذَٰلِكَ نُفَصِّلُ الْآيَاتِ وَلَعَلَّهُمْ يَرْجِعُونَ‘‘ — اور — اسی طرح — ہم — آیات کو تفصیل سے — بیان کر رہے ہیں — اور شاید — وہ — لوٹ آئیں — یعنی آیات اللہ — انسانوں کو — توبہ اور رجوع کی دعوت دیتے ہیں۔
۳۔ عملی سبق: آیاتِ اللہ — موقعِ واپسی دیتی ہیں؛ امید رہے۔"""
),
}
